<?php require_once __DIR__.'/../includes/auth.php'; require_role(['student']); $pageTitle='Notifications'; require __DIR__.'/../includes/header.php'; $s=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 100');$s->execute([current_user()['id']]);$rows=$s->fetchAll();echo '<h1>Notifications</h1><div class="list">';foreach($rows as $r){echo '<article class="item-card"><p>'.e($r['message']).'</p><small>'.e($r['created_at']).' · '.($r['read_at']?'Read':'Unread').'</small></article>';}if(!$rows)echo '<div class="empty">No notifications yet.</div>';echo '</div>'; require __DIR__.'/../includes/footer.php'; ?>